import{_ as n,c as h,o as i,a2 as a}from"./chunks/framework.B7el9cAC.js";const m=JSON.parse('{"title":"Mục 6.2 – An Toàn Thông Tin","description":"","frontmatter":{},"headers":[],"relativePath":"chuong-6/6.2-an-toan-thong-tin.md","filePath":"chuong-6/6.2-an-toan-thong-tin.md","lastUpdated":1775365196000}'),o={name:"chuong-6/6.2-an-toan-thong-tin.md"};function g(r,t,c,d,e,l){return i(),h("div",null,[...t[0]||(t[0]=[a('<h1 id="muc-6-2-–-an-toan-thong-tin" tabindex="-1">Mục 6.2 – An Toàn Thông Tin <a class="header-anchor" href="#muc-6-2-–-an-toan-thong-tin" aria-label="Permalink to &quot;Mục 6.2 – An Toàn Thông Tin&quot;">​</a></h1><hr><h2 id="🔹-1-gioi-thieu-sieu-co-ban" tabindex="-1">🔹 1. GIỚI THIỆU SIÊU CƠ BẢN <a class="header-anchor" href="#🔹-1-gioi-thieu-sieu-co-ban" aria-label="Permalink to &quot;🔹 1. GIỚI THIỆU SIÊU CƠ BẢN&quot;">​</a></h2><p><strong>Tại sao cần học an toàn thông tin?</strong></p><p>Hãy tưởng tượng bạn có một chiếc két sắt đựng toàn bộ tài sản, giấy tờ quan trọng, hình ảnh gia đình. Bạn có để chiếc két đó mở toàn, cài mật khẩu &quot;1234&quot;, hay dán nhãn &quot;ĐÂY LÀ CỦA TÔI – MẬT KHẨU: 1234&quot; lên ngoài không?</p><p>Tất nhiên là không. Nhưng nhiều người đang làm điều y chang với <strong>dữ liệu số</strong> của mình.</p><p><strong>Thực tế đáng lo ngại:</strong></p><ul><li>Mỗi ngày có hơn <strong>300.000 phần mềm độc hại</strong> mới được tạo ra</li><li>Việt Nam nằm trong top 10 quốc gia bị tấn công mạng nhiều nhất châu Á</li><li>80% người dùng dùng lại cùng một mật khẩu cho nhiều tài khoản</li></ul><p>An toàn thông tin không chỉ là vấn đề của doanh nghiệp – nó ảnh hưởng đến <strong>mỗi cá nhân</strong> hàng ngày.</p><hr><h2 id="🔹-2-ly-thuyet-chi-tiet" tabindex="-1">🔹 2. LÝ THUYẾT CHI TIẾT <a class="header-anchor" href="#🔹-2-ly-thuyet-chi-tiet" aria-label="Permalink to &quot;🔹 2. LÝ THUYẾT CHI TIẾT&quot;">​</a></h2><h3 id="an-toan-thong-tin-la-gi" tabindex="-1">An toàn thông tin là gì? <a class="header-anchor" href="#an-toan-thong-tin-la-gi" aria-label="Permalink to &quot;An toàn thông tin là gì?&quot;">​</a></h3><p><strong>An toàn thông tin (Information Security / InfoSec)</strong> là tập hợp các biện pháp, quy trình và công nghệ nhằm bảo vệ thông tin khỏi:</p><ul><li><strong>Truy cập trái phép</strong> (người không được phép đọc được)</li><li><strong>Sửa đổi trái phép</strong> (dữ liệu bị thay đổi mà không biết)</li><li><strong>Phá hủy</strong> (dữ liệu bị xóa hoặc mã hóa đòi tiền chuộc)</li></ul><p><strong>3 nguyên tắc cốt lõi (CIA Triad):</strong></p><ul><li><strong>C – Confidentiality (Bí mật):</strong> Chỉ người được phép mới đọc được</li><li><strong>I – Integrity (Toàn vẹn):</strong> Dữ liệu không bị thay đổi trái phép</li><li><strong>A – Availability (Sẵn sàng):</strong> Dữ liệu luôn có thể truy cập khi cần</li></ul><h3 id="hacker-la-gi" tabindex="-1">Hacker là gì? <a class="header-anchor" href="#hacker-la-gi" aria-label="Permalink to &quot;Hacker là gì?&quot;">​</a></h3><p><strong>Hacker</strong> = người có kỹ năng kỹ thuật sâu về hệ thống máy tính, mạng, và bảo mật.</p><table tabindex="0"><thead><tr><th>Loại</th><th>Biệt danh</th><th>Mục đích</th><th>Hợp pháp?</th></tr></thead><tbody><tr><td><strong>White Hat (Mũ trắng)</strong></td><td>Ethical Hacker</td><td>Tìm lỗ hổng để vá, được thuê bởi công ty</td><td>✅ Có</td></tr><tr><td><strong>Black Hat (Mũ đen)</strong></td><td>Cracker</td><td>Tấn công để ăn cắp dữ liệu, phá hoại</td><td>❌ Không</td></tr><tr><td><strong>Grey Hat (Mũ xám)</strong></td><td>—</td><td>Tìm lỗ hổng không được phép, rồi thông báo</td><td>Mập mờ</td></tr></tbody></table><h3 id="cac-moi-đe-doa-pho-bien" tabindex="-1">Các mối đe dọa phổ biến <a class="header-anchor" href="#cac-moi-đe-doa-pho-bien" aria-label="Permalink to &quot;Các mối đe dọa phổ biến&quot;">​</a></h3><p><strong>Virus máy tính:</strong></p><ul><li>Phần mềm độc hại tự sao chép và lây lan từ file sang file</li><li>Cần &quot;ký chủ&quot; (file hoặc chương trình) để lây lan</li><li>Ví dụ: Virus lây qua USB, email đính kèm</li></ul><p><strong>Malware (Phần mềm độc hại):</strong></p><ul><li>Thuật ngữ tổng quát cho mọi phần mềm gây hại</li><li>Bao gồm: virus, worm, trojan, ransomware, spyware, adware</li><li><strong>Ransomware:</strong> Mã hóa dữ liệu của bạn, đòi tiền chuộc để khóa</li><li><strong>Spyware:</strong> Âm thầm theo dõi hoạt động, ăn cắp mật khẩu</li></ul><p><strong>Phishing (Lừa đảo):</strong></p><ul><li>Giả mạo email, tin nhắn, website để lừa bạn nhập thông tin</li><li>Ví dụ: Email giả ngân hàng nói &quot;Tài khoản bị khóa, click vào đây để xác minh&quot;</li><li>Website giả y chang Facebook để lấy mật khẩu</li></ul><h3 id="mat-khau-manh" tabindex="-1">Mật khẩu mạnh <a class="header-anchor" href="#mat-khau-manh" aria-label="Permalink to &quot;Mật khẩu mạnh&quot;">​</a></h3><p><strong>Mật khẩu yếu (dễ bị hack):</strong></p><ul><li><code>123456</code>, <code>password</code>, <code>abcdef</code></li><li>Tên + ngày sinh: <code>Nam2009</code>, <code>Lan0205</code></li><li>Từ có trong từ điển: <code>hello</code>, <code>sunshine</code></li></ul><p><strong>Mật khẩu mạnh:</strong></p><ul><li>Ít nhất <strong>12 ký tự</strong></li><li>Kết hợp: Chữ hoa + chữ thường + số + ký tự đặc biệt</li><li>Ví dụ mạnh: <code>Tr@nV@n$An#2024!</code></li><li>Không dùng thông tin cá nhân dễ đoán</li></ul><hr><h2 id="🔹-3-giai-thich-ban-chat" tabindex="-1">🔹 3. GIẢI THÍCH BẢN CHẤT <a class="header-anchor" href="#🔹-3-giai-thich-ban-chat" aria-label="Permalink to &quot;🔹 3. GIẢI THÍCH BẢN CHẤT&quot;">​</a></h2><p><strong>An toàn thông tin giống như bảo vệ ngôi nhà của bạn:</strong></p><table tabindex="0"><thead><tr><th>Bảo vệ nhà</th><th>Bảo vệ thông tin số</th></tr></thead><tbody><tr><td>Khóa cửa</td><td>Mật khẩu mạnh</td></tr><tr><td>Camera an ninh</td><td>Phần mềm diệt virus</td></tr><tr><td>Chỉ cho người quen vào</td><td>Không click link lạ</td></tr><tr><td>Kiểm tra người lạ gõ cửa</td><td>Xác minh email/website trước khi nhập thông tin</td></tr><tr><td>Lắp thêm khóa</td><td>Bật xác thực 2 yếu tố (2FA)</td></tr><tr><td>Sao lưu giấy tờ quan trọng</td><td>Backup dữ liệu</td></tr></tbody></table><p><strong>Phishing giống như thế nào trong thực tế?</strong></p><p>Giống như kẻ lừa đảo mặc đồng phục ngân hàng, gọi điện nói &quot;Tài khoản bạn bị đóng băng, cho tôi xin số thẻ và OTP để mở lại.&quot; Đó là lừa đảo – ngân hàng thật <strong>không bao giờ</strong> hỏi mật khẩu/OTP qua điện thoại.</p><hr><h2 id="🔹-4-luong-hoat-đong-step-by-step" tabindex="-1">🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP <a class="header-anchor" href="#🔹-4-luong-hoat-đong-step-by-step" aria-label="Permalink to &quot;🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP&quot;">​</a></h2><h3 id="cach-mot-cuoc-tan-cong-phishing-hoat-đong" tabindex="-1">Cách một cuộc tấn công Phishing hoạt động: <a class="header-anchor" href="#cach-mot-cuoc-tan-cong-phishing-hoat-đong" aria-label="Permalink to &quot;Cách một cuộc tấn công Phishing hoạt động:&quot;">​</a></h3><ol><li><strong>Hacker tạo email giả</strong> → Giả mạo logo, tên miền gần giống thật (ví dụ: <code>vietcombank.com.vn</code> vs <code>vietc0mbank.com.vn</code>)</li><li><strong>Gửi đại trà</strong> → Gửi hàng triệu email; chỉ cần 1% người tin là đủ</li><li><strong>Nạn nhân nhấp link</strong> → Chuyển đến website giả có giao diện y chang thật</li><li><strong>Nạn nhân nhập thông tin</strong> → Tên đăng nhập, mật khẩu, số thẻ, OTP</li><li><strong>Hacker thu thập</strong> → Nhận thông tin ngay lập tức</li><li><strong>Chiếm đoạt tài khoản</strong> → Đăng nhập tài khoản thật, chuyển tiền hoặc đánh cắp dữ liệu</li></ol><h3 id="cach-bao-ve-ban-than" tabindex="-1">Cách bảo vệ bản thân: <a class="header-anchor" href="#cach-bao-ve-ban-than" aria-label="Permalink to &quot;Cách bảo vệ bản thân:&quot;">​</a></h3><ol><li><strong>Dùng mật khẩu mạnh và khác nhau</strong> cho mỗi tài khoản</li><li><strong>Bật xác thực 2 yếu tố (2FA)</strong> – yêu cầu mã OTP khi đăng nhập</li><li><strong>Cập nhật phần mềm</strong> thường xuyên – vá lỗ hổng bảo mật</li><li><strong>Cài phần mềm diệt virus</strong> từ nguồn uy tín</li><li><strong>Kiểm tra URL</strong> trước khi nhập thông tin – phải là <code>https://</code> và đúng tên miền</li><li><strong>Không click link lạ</strong> trong email, SMS, Zalo từ người không quen</li><li><strong>Backup dữ liệu</strong> định kỳ (lưu vào ổ cứng ngoài hoặc cloud)</li><li><strong>Dùng mạng WiFi an toàn</strong> – tránh WiFi công cộng khi đăng nhập tài khoản quan trọng</li></ol><hr><h2 id="🔹-5-vi-du-minh-hoa" tabindex="-1">🔹 5. VÍ DỤ MINH HỌA <a class="header-anchor" href="#🔹-5-vi-du-minh-hoa" aria-label="Permalink to &quot;🔹 5. VÍ DỤ MINH HỌA&quot;">​</a></h2><h3 id="vi-du-1-–-co-ban-phan-biet-mat-khau-yeu-va-manh" tabindex="-1">Ví dụ 1 – Cơ bản: Phân biệt mật khẩu yếu và mạnh <a class="header-anchor" href="#vi-du-1-–-co-ban-phan-biet-mat-khau-yeu-va-manh" aria-label="Permalink to &quot;Ví dụ 1 – Cơ bản: Phân biệt mật khẩu yếu và mạnh&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mật khẩu</th><th>Đánh giá</th><th>Lý do</th></tr></thead><tbody><tr><td><code>123456</code></td><td>❌ Rất yếu</td><td>Phổ biến nhất thế giới, bị crack &lt; 1 giây</td></tr><tr><td><code>HoaHong</code></td><td>❌ Yếu</td><td>Chỉ chữ thường, từ có nghĩa</td></tr><tr><td><code>An2009THPT</code></td><td>⚠️ Trung bình</td><td>Có số nhưng chứa thông tin cá nhân</td></tr><tr><td><code>X#7mK!9vPq@2</code></td><td>✅ Mạnh</td><td>12 ký tự, hỗn hợp, không có nghĩa</td></tr><tr><td><code>Tr@iCayXo@iM@ng!</code></td><td>✅ Rất mạnh</td><td>Dài, có ký tự đặc biệt, dễ nhớ theo câu</td></tr></tbody></table><hr><h3 id="vi-du-2-–-thuc-te-nhan-dien-email-phishing" tabindex="-1">Ví dụ 2 – Thực tế: Nhận diện email Phishing <a class="header-anchor" href="#vi-du-2-–-thuc-te-nhan-dien-email-phishing" aria-label="Permalink to &quot;Ví dụ 2 – Thực tế: Nhận diện email Phishing&quot;">​</a></h3><p><strong>Email bạn nhận được:</strong></p><blockquote><p><strong>Từ:</strong> <a href="mailto:support@zalopay-security.net" target="_blank" rel="noreferrer">support@zalopay-security.net</a><br><strong>Tiêu đề:</strong> 🚨 Tài khoản ZaloPay của bạn bị khóa khẩn cấp!<br><strong>Nội dung:</strong> &quot;Tài khoản của bạn bị phát hiện hoạt động bất thường. Click vào link dưới để xác minh ngay, nếu không tài khoản sẽ bị xóa trong 24 giờ.&quot;<br><strong>Link:</strong> <code>http://zalopay-xacminh-tai-khoan.xyz/login</code></p></blockquote><p><strong>Dấu hiệu đây là Phishing:</strong></p><ul><li>Tên miền email: <code>zalopay-security.net</code> (ZaloPay thật dùng <code>@zalopay.vn</code>)</li><li>Tạo cảm giác <strong>khẩn cấp, sợ hãi</strong> – chiêu cổ điển của lừa đảo</li><li>Link dẫn đến <code>.xyz</code> – không phải tên miền chính thức</li><li>Không gọi tên bạn cụ thể (email lừa đảo gửi đại trà)</li></ul><p><strong>Hành động đúng:</strong> Xóa email. Mở app ZaloPay trực tiếp để kiểm tra. Không bao giờ click link trong email nghi ngờ.</p><hr><h3 id="vi-du-3-–-nang-cao-ransomware-tan-cong" tabindex="-1">Ví dụ 3 – Nâng cao: Ransomware tấn công <a class="header-anchor" href="#vi-du-3-–-nang-cao-ransomware-tan-cong" aria-label="Permalink to &quot;Ví dụ 3 – Nâng cao: Ransomware tấn công&quot;">​</a></h3><p><strong>Tình huống:</strong> Một học sinh tải phần mềm bẻ khóa game miễn phí từ website lạ. Sau khi cài, toàn bộ file bài tập, ảnh gia đình bị mã hóa. Màn hình hiện thông báo:</p><blockquote><p><em>&quot;Tất cả file của bạn đã bị mã hóa. Hãy chuyển 500 USD Bitcoin để nhận key mở khóa trong 48 giờ.&quot;</em></p></blockquote><p><strong>Phân tích:</strong></p><ul><li>Phần mềm bẻ khóa game = <strong>Trojan</strong> chứa Ransomware ẩn bên trong</li><li>Ransomware mã hóa file → nạn nhân không đọc được → đòi tiền chuộc</li></ul><p><strong>Bài học:</strong></p><ol><li>Không bao giờ tải phần mềm crack/keygen từ nguồn không tin cậy</li><li>Luôn backup dữ liệu → nếu bị Ransomware vẫn còn bản sao</li><li>Không trả tiền chuộc – không đảm bảo hacker giải mã, và khuyến khích tội phạm</li></ol><hr><h2 id="🔹-6-so-sanh-phan-biet" tabindex="-1">🔹 6. SO SÁNH &amp; PHÂN BIỆT <a class="header-anchor" href="#🔹-6-so-sanh-phan-biet" aria-label="Permalink to &quot;🔹 6. SO SÁNH &amp; PHÂN BIỆT&quot;">​</a></h2><h3 id="so-sanh-cac-loai-phan-mem-đoc-hai" tabindex="-1">So sánh các loại phần mềm độc hại <a class="header-anchor" href="#so-sanh-cac-loai-phan-mem-đoc-hai" aria-label="Permalink to &quot;So sánh các loại phần mềm độc hại&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Loại</th><th>Cách lây lan</th><th>Tác hại chính</th></tr></thead><tbody><tr><td><strong>Virus</strong></td><td>Lây qua file/USB</td><td>Phá hủy file, làm chậm máy</td></tr><tr><td><strong>Worm</strong></td><td>Tự lây qua mạng</td><td>Chiếm băng thông, tạo botnet</td></tr><tr><td><strong>Trojan</strong></td><td>Giả mạo phần mềm hợp lệ</td><td>Mở cửa hậu cho hacker</td></tr><tr><td><strong>Ransomware</strong></td><td>Thường qua Trojan/email</td><td>Mã hóa dữ liệu, đòi tiền chuộc</td></tr><tr><td><strong>Spyware</strong></td><td>Cài ngầm</td><td>Theo dõi, ăn cắp mật khẩu</td></tr><tr><td><strong>Adware</strong></td><td>Cài kèm phần mềm miễn phí</td><td>Hiển thị quảng cáo, chuyển hướng</td></tr></tbody></table><h3 id="so-sanh-white-hat-va-black-hat-hacker" tabindex="-1">So sánh White Hat và Black Hat Hacker <a class="header-anchor" href="#so-sanh-white-hat-va-black-hat-hacker" aria-label="Permalink to &quot;So sánh White Hat và Black Hat Hacker&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tiêu chí</th><th>White Hat</th><th>Black Hat</th></tr></thead><tbody><tr><td>Mục đích</td><td>Bảo vệ hệ thống</td><td>Tấn công, ăn cắp</td></tr><tr><td>Phép tắc</td><td>Có hợp đồng/ủy quyền</td><td>Không phép</td></tr><tr><td>Kết quả</td><td>Báo cáo lỗ hổng để vá</td><td>Khai thác lỗ hổng kiếm lợi</td></tr><tr><td>Pháp lý</td><td>Hợp pháp</td><td>Vi phạm pháp luật</td></tr><tr><td>Nghề nghiệp</td><td>Chuyên gia bảo mật</td><td>Tội phạm mạng</td></tr></tbody></table><hr><h2 id="🔹-7-ghi-nho-nhanh-đi-thi" tabindex="-1">🔹 7. GHI NHỚ NHANH (ĐI THI) <a class="header-anchor" href="#🔹-7-ghi-nho-nhanh-đi-thi" aria-label="Permalink to &quot;🔹 7. GHI NHỚ NHANH (ĐI THI)&quot;">​</a></h2><ul><li>✅ <strong>An toàn thông tin</strong> = bảo vệ tính Bí mật, Toàn vẹn, Sẵn sàng của dữ liệu (CIA)</li><li>✅ <strong>White Hat</strong> = hacker mũ trắng, hợp pháp, bảo vệ hệ thống</li><li>✅ <strong>Black Hat</strong> = hacker mũ đen, bất hợp pháp, tấn công phá hoại</li><li>✅ <strong>Virus</strong> = lây qua file; <strong>Worm</strong> = tự lây qua mạng; <strong>Trojan</strong> = giả phần mềm tốt</li><li>✅ <strong>Ransomware</strong> = mã hóa dữ liệu đòi tiền chuộc</li><li>✅ <strong>Phishing</strong> = giả mạo để lừa nhập thông tin</li><li>✅ Mật khẩu mạnh: <strong>≥12 ký tự</strong>, chữ hoa + thường + số + ký tự đặc biệt</li><li>✅ <strong>2FA (Xác thực 2 yếu tố)</strong> = lớp bảo vệ thứ 2 sau mật khẩu</li><li>✅ Nhận email lạ: <strong>không click link, không nhập thông tin</strong></li></ul><hr><h2 id="🔹-8-bai-tap-tu-luyen" tabindex="-1">🔹 8. BÀI TẬP TỰ LUYỆN <a class="header-anchor" href="#🔹-8-bai-tap-tu-luyen" aria-label="Permalink to &quot;🔹 8. BÀI TẬP TỰ LUYỆN&quot;">​</a></h2><h3 id="cau-1-de-white-hat-hacker-la-gi" tabindex="-1">Câu 1 (Dễ): &quot;White Hat Hacker&quot; là gì? <a class="header-anchor" href="#cau-1-de-white-hat-hacker-la-gi" aria-label="Permalink to &quot;Câu 1 (Dễ): &quot;White Hat Hacker&quot; là gì?&quot;">​</a></h3><blockquote><p><strong>Đáp án:</strong> Là chuyên gia bảo mật được thuê để tìm lỗ hổng trong hệ thống một cách hợp pháp, sau đó báo cáo để được vá. Họ làm điều hacker xấu làm, nhưng có sự cho phép và mục đích bảo vệ.</p></blockquote><hr><h3 id="cau-2-de-mat-khau-nao-sau-đay-la-manh-nhat" tabindex="-1">Câu 2 (Dễ): Mật khẩu nào sau đây là mạnh nhất? <a class="header-anchor" href="#cau-2-de-mat-khau-nao-sau-đay-la-manh-nhat" aria-label="Permalink to &quot;Câu 2 (Dễ): Mật khẩu nào sau đây là mạnh nhất?&quot;">​</a></h3><p><strong>A.</strong> <code>hoa123</code><br><strong>B.</strong> <code>NguyenVanAn2009</code><br><strong>C.</strong> <code>P@ssw0rd</code><br><strong>D.</strong> <code>kR#9mL!xW2@pQ</code></p><blockquote><p><strong>Đáp án: D</strong> – Dài 14 ký tự, không có nghĩa, kết hợp chữ hoa/thường/số/ký tự đặc biệt. Lưu ý: C trông phức tạp nhưng là mẫu phổ biến đã bị liệt kê trong danh sách từ điển hack.</p></blockquote><hr><h3 id="cau-3-trung-binh-su-khac-nhau-giua-virus-va-ransomware-la-gi" tabindex="-1">Câu 3 (Trung bình): Sự khác nhau giữa <strong>Virus</strong> và <strong>Ransomware</strong> là gì? <a class="header-anchor" href="#cau-3-trung-binh-su-khac-nhau-giua-virus-va-ransomware-la-gi" aria-label="Permalink to &quot;Câu 3 (Trung bình): Sự khác nhau giữa **Virus** và **Ransomware** là gì?&quot;">​</a></h3><blockquote><p><strong>Đáp án:</strong> Virus là loại malware tự sao chép, lây lan từ file sang file, thường phá hoại hoặc làm chậm máy. Ransomware là loại malware chuyên biệt mã hóa toàn bộ dữ liệu người dùng và yêu cầu trả tiền (thường bằng tiền điện tử) để nhận key giải mã. Ransomware nguy hiểm hơn vì nhắm trực tiếp vào dữ liệu quan trọng và tạo ra thiệt hại tài chính.</p></blockquote><hr><h3 id="cau-4-trung-binh-ban-nhan-email-tu-ngan-hang-yeu-cau-xac-minh-tai-khoan-lam-the-nao-đe-xac-đinh-đay-co-phai-phishing-khong" tabindex="-1">Câu 4 (Trung bình): Bạn nhận email từ &quot;ngân hàng&quot; yêu cầu xác minh tài khoản. Làm thế nào để xác định đây có phải Phishing không? <a class="header-anchor" href="#cau-4-trung-binh-ban-nhan-email-tu-ngan-hang-yeu-cau-xac-minh-tai-khoan-lam-the-nao-đe-xac-đinh-đay-co-phai-phishing-khong" aria-label="Permalink to &quot;Câu 4 (Trung bình): Bạn nhận email từ &quot;ngân hàng&quot; yêu cầu xác minh tài khoản. Làm thế nào để xác định đây có phải Phishing không?&quot;">​</a></h3><blockquote><p><strong>Đáp án:</strong> Kiểm tra: (1) Địa chỉ email người gửi – có khớp tên miền chính thức không? (2) URL link trong email – hover chuột để xem địa chỉ thật; (3) Nội dung có tạo cảm giác khẩn cấp, sợ hãi không? (4) Có gọi tên bạn cụ thể không (email thật thường có tên)? (5) Có yêu cầu mật khẩu/OTP không? – ngân hàng thật <strong>không bao giờ</strong> hỏi.</p></blockquote><hr><h3 id="cau-5-van-dung-ban-muon-tao-mat-khau-manh-cho-tai-khoan-email-quan-trong-hay-đe-xuat-mot-phuong-phap-tao-mat-khau-vua-manh-vua-de-nho" tabindex="-1">Câu 5 (Vận dụng): Bạn muốn tạo mật khẩu mạnh cho tài khoản email quan trọng. Hãy đề xuất một phương pháp tạo mật khẩu vừa mạnh vừa dễ nhớ. <a class="header-anchor" href="#cau-5-van-dung-ban-muon-tao-mat-khau-manh-cho-tai-khoan-email-quan-trong-hay-đe-xuat-mot-phuong-phap-tao-mat-khau-vua-manh-vua-de-nho" aria-label="Permalink to &quot;Câu 5 (Vận dụng): Bạn muốn tạo mật khẩu mạnh cho tài khoản email quan trọng. Hãy đề xuất một phương pháp tạo mật khẩu vừa mạnh vừa dễ nhớ.&quot;">​</a></h3><blockquote><p><strong>Đáp án:</strong> Phương pháp <strong>Passphrase (câu mật khẩu):</strong> Chọn một câu bạn nhớ được, lấy chữ cái đầu mỗi từ, thay một số chữ bằng ký tự tương tự.</p><p>Ví dụ: <em>&quot;Tôi học lớp mười tại trường Nguyễn Huệ năm 2024!&quot;</em><br> → <code>ThlmttNHn2024!</code></p><p>Hoặc dùng câu đầy đủ có thay thế: <code>T0i-H0c-L0p-Mu0i!</code> → dễ nhớ, khó đoán. Luôn dùng mật khẩu khác nhau cho mỗi tài khoản; dùng <strong>Password Manager</strong> (phần mềm quản lý mật khẩu) để lưu.</p></blockquote><hr><h2 id="🔹-9-loi-thuong-gap" tabindex="-1">🔹 9. LỖI THƯỜNG GẶP <a class="header-anchor" href="#🔹-9-loi-thuong-gap" aria-label="Permalink to &quot;🔹 9. LỖI THƯỜNG GẶP&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Quan niệm/Hành vi sai</th><th>Thực tế đúng</th></tr></thead><tbody><tr><td>&quot;Máy tính của mình không ai hack, mình không quan trọng&quot;</td><td>Hacker tấn công tự động hàng loạt, ai cũng có thể là mục tiêu</td></tr><tr><td>Dùng cùng 1 mật khẩu cho tất cả tài khoản</td><td>Nếu 1 tài khoản bị hack → tất cả bị hack</td></tr><tr><td>Click link trong email mà không kiểm tra</td><td>Phishing chiếm tỷ lệ cao nhất trong các cuộc tấn công</td></tr><tr><td>Tắt cập nhật tự động vì &quot;chậm máy&quot;</td><td>Cập nhật vá các lỗ hổng bảo mật nghiêm trọng</td></tr><tr><td>Dùng WiFi công cộng để đăng nhập ngân hàng</td><td>WiFi công cộng có thể bị nghe lén (man-in-the-middle)</td></tr><tr><td>Nghĩ antivirus là đủ để bảo vệ</td><td>Antivirus chỉ là 1 lớp bảo vệ; cần kết hợp nhiều biện pháp</td></tr><tr><td>Trả tiền chuộc cho Ransomware</td><td>Không đảm bảo lấy lại được data; nuôi dưỡng tội phạm</td></tr><tr><td>Mật khẩu dài là đủ mạnh</td><td>Mật khẩu cần có chữ hoa, thường, số và ký tự đặc biệt; độ phức tạp quan trọng hơn độ dài đơn thuần</td></tr><tr><td>2FA qua SMS là an toàn tuyệt đối</td><td>SMS 2FA có thể bị tấn công SIM swapping; dùng app xác thực (Google Authenticator) an toàn hơn</td></tr><tr><td>File PDF không chứa được virus</td><td>File PDF có thể nhúng mã độc và khai thác lỗ hổng trình đọc PDF</td></tr><tr><td>Chỉ cần đặt mật khẩu máy tính là đủ</td><td>Cần mã hóa ổ cứng (BitLocker/FileVault) vì tháo ổ cứng ra có thể đọc dữ liệu trực tiếp</td></tr><tr><td>Hacker nhất định ngồi phòng tối nhìn màn hình code phức tạp</td><td>Hacker thường dùng kỹ thuật xã hội (social engineering) bình thường, không cần kỹ năng kỹ thuật cao</td></tr><tr><td>Antivirus miễn phí luôn kém hơn trả phí</td><td>Nhiều antivirus miễn phí (Windows Defender, Malwarebytes) hiệu quả tương đương cho người dùng thông thường</td></tr><tr><td>Xóa file là xóa vĩnh viễn</td><td>File đã xóa vẫn có thể khôi phục bằng phần mềm forensics; cần dùng secure delete</td></tr><tr><td>VPN là công cụ của kẻ xấu</td><td>VPN là công cụ bảo mật hợp pháp, được dùng rộng rãi trong doanh nghiệp và bởi người dùng cá nhân</td></tr><tr><td>Website có HTTPS là hoàn toàn an toàn</td><td>HTTPS chỉ mã hóa truyền tải; website HTTPS vẫn có thể chứa phishing hoặc mã độc</td></tr><tr><td>Đặt câu hỏi bảo mật dễ nhớ là tiện và an toàn</td><td>Câu hỏi bảo mật dễ đoán (tên mẹ, trường học) dễ bị social engineering khai thác</td></tr><tr><td>Mạng của công ty/trường học là hoàn toàn an toàn</td><td>Mạng nội bộ vẫn có thể bị tấn công từ bên trong; không nên mất cảnh giác</td></tr><tr><td>Tài khoản người thân không bao giờ dùng để lừa mình</td><td>Tài khoản người thân có thể bị hack và dùng để lừa bạn (Business Email Compromise)</td></tr><tr><td>Chỉ tải từ App Store/Google Play là hoàn toàn an toàn</td><td>Đã có nhiều app độc hại vượt qua kiểm duyệt của App Store và Play Store</td></tr><tr><td>Điện thoại iPhone không bị hack</td><td>iPhone cũng có lỗ hổng bảo mật; Pegasus spyware đã tấn công nhiều iPhone</td></tr><tr><td>Đặt tên WiFi và mật khẩu mặc định của router không sao</td><td>Router mặc định dễ bị tấn công; cần đổi tên và mật khẩu ngay khi cài đặt</td></tr><tr><td>Logout tài khoản là đủ khi dùng máy công cộng</td><td>Cần xóa cache, lịch sử và đảm bảo không lưu mật khẩu khi dùng máy công cộng</td></tr><tr><td>Phishing chỉ đến qua email</td><td>Phishing còn qua SMS (smishing), điện thoại (vishing), mạng xã hội và QR code</td></tr><tr><td>Tôi sẽ biết ngay khi bị hack</td><td>Nhiều cuộc tấn công không để lại dấu hiệu rõ ràng; có thể bị xâm nhập hàng tháng mà không biết</td></tr><tr><td>Mật khẩu ngày sinh hoặc tên là dễ nhớ và đủ dùng</td><td>Đây là mật khẩu đầu tiên bị thử trong tấn công brute force và social engineering</td></tr><tr><td>Kiểm tra email lừa đảo bằng tên người gửi là đủ</td><td>Email giả mạo có thể hiển thị đúng tên; cần kiểm tra địa chỉ email thực đầy đủ</td></tr><tr><td>Backup 1 lần là đủ</td><td>Backup cần định kỳ và kiểm tra khả năng phục hồi; backup cũ trở nên vô dụng nhanh chóng</td></tr><tr><td>Firewall là đủ để chặn mọi tấn công mạng</td><td>Firewall chặn tấn công từ bên ngoài nhưng không chặn được insider threat hoặc zero-day attacks</td></tr><tr><td>Bật Bluetooth và WiFi liên tục không nguy hiểm</td><td>Bluetooth và WiFi mở tạo bề mặt tấn công; nên tắt khi không dùng</td></tr><tr><td>App xin nhiều quyền là app tốt vì cần nhiều tính năng</td><td>App xin quyền không cần thiết (đèn pin xin danh bạ) là dấu hiệu đáng ngờ</td></tr><tr><td>Đổi mật khẩu hàng tháng là thói quen tốt nhất</td><td>Đổi mật khẩu quá thường khiến người dùng chọn mật khẩu yếu hơn; đổi khi có nghi ngờ bị lộ</td></tr><tr><td>Tin nhắn &quot;Tài khoản sắp khóa&quot; luôn là thật</td><td>Đây là dạng phishing phổ biến; cần truy cập trực tiếp website chính thức để kiểm tra</td></tr><tr><td>Dữ liệu trên cloud an toàn hơn máy tính mà không cần làm gì thêm</td><td>Cloud bảo mật tốt nhưng cần kết hợp với mật khẩu mạnh và 2FA; nhà cung cấp vẫn có thể bị hack</td></tr><tr><td>Chia sẻ mật khẩu với người thân là bình thường</td><td>Chia sẻ mật khẩu tạo rủi ro ngay cả với người thân; tốt hơn dùng tính năng chia sẻ tích hợp</td></tr><tr><td>Trẻ em không phải mục tiêu của hacker</td><td>Trẻ em thường bị nhắm mục tiêu qua game online và mạng xã hội để lấy dữ liệu cha mẹ</td></tr><tr><td>Mã OTP không bao giờ bị đánh cắp</td><td>OTP có thể bị đánh cắp qua social engineering hoặc real-time phishing attacks</td></tr><tr><td>Chỉ truy cập website người lớn mới bị virus</td><td>Malvertising có thể nhiễm virus qua quảng cáo trên bất kỳ website nào, kể cả báo uy tín</td></tr><tr><td>Máy Mac không cần antivirus</td><td>macOS cũng có malware; số lượng ngày càng tăng theo thị phần</td></tr><tr><td>Đổi mật khẩu sau khi bị hack là đủ</td><td>Sau khi bị hack cần: đổi mật khẩu, kiểm tra session đang mở, revoke token và bật 2FA</td></tr><tr><td>Hacker phải ngồi gần mạng WiFi mới tấn công được</td><td>Nhiều cuộc tấn công thực hiện từ xa qua internet mà không cần ở gần nạn nhân</td></tr><tr><td>Phần mềm từ bạn bè gửi là an toàn</td><td>File từ bạn bè cũng có thể nhiễm mã độc mà bạn bè không biết</td></tr><tr><td>Kiểm tra URL chỉ cần nhìn tên miền là đủ</td><td>Cần kiểm tra toàn bộ URL; &#39;paypal.com.evil.com&#39; có &#39;paypal.com&#39; nhưng domain thật là &#39;evil.com&#39;</td></tr><tr><td>Tài khoản mạng xã hội không cần bảo mật cao</td><td>Tài khoản mạng xã hội bị chiếm có thể dùng để lừa đảo, phát tán malware</td></tr><tr><td>Ghi mật khẩu ra giấy là luôn không an toàn</td><td>Giấy trong két an toàn tại nhà an toàn hơn file mật khẩu không mã hóa trên máy tính</td></tr><tr><td>Extension trình duyệt từ Chrome Web Store đều an toàn</td><td>Đã có nhiều extension độc hại trên Chrome Web Store bị phát hiện đánh cắp dữ liệu</td></tr><tr><td>Tấn công mạng chỉ xảy ra với hệ thống lớn</td><td>SME và cá nhân thường bị tấn công nhiều hơn vì bảo mật kém hơn</td></tr><tr><td>Reset máy tính là xóa sạch mọi thứ</td><td>Factory reset không đảm bảo xóa sạch; cần dùng công cụ ghi đè dữ liệu (secure erase)</td></tr><tr><td>Ngay cả chuyên gia cũng không bị lừa bởi phishing</td><td>Ngay cả chuyên gia bảo mật cũng có thể bị lừa bởi phishing tinh vi được cá nhân hóa</td></tr><tr><td>Chỉ cần không mở file .exe là an toàn</td><td>Mã độc có thể ẩn trong .pdf, .doc, .jpg và cả macro trong Excel</td></tr><tr><td>Dùng password manager rủi ro hơn tự nhớ mật khẩu</td><td>Password manager mã hóa và tạo mật khẩu mạnh; an toàn hơn nhiều so với tự nhớ mật khẩu yếu</td></tr><tr><td>Mạng 4G/5G hoàn toàn an toàn hơn WiFi</td><td>Mạng di động cũng có thể bị tấn công bằng IMSI catcher; không hoàn toàn an toàn</td></tr><tr><td>Cài đặt bảo mật mặc định của thiết bị mới là đủ</td><td>Thiết bị mới thường có cài đặt ưu tiên tiện lợi hơn bảo mật; cần tùy chỉnh thêm</td></tr><tr><td>Tên người dùng không cần giữ bí mật</td><td>Username kết hợp với thông tin khác giúp hacker tấn công brute force dễ hơn</td></tr><tr><td>Dùng cùng username ở mọi nơi giúp dễ nhớ và không hại gì</td><td>Cùng username giúp kẻ tấn công dễ dàng tổng hợp thông tin về bạn từ nhiều nền tảng</td></tr><tr><td>Bảo mật là trách nhiệm của bộ phận IT, không phải người dùng</td><td>Người dùng là tuyến phòng thủ quan trọng nhất; hầu hết vi phạm bắt đầu từ lỗi con người</td></tr><tr><td>Phần mềm crack an toàn nếu antivirus không phát hiện gì</td><td>Phần mềm crack thường chứa mã độc ẩn mà antivirus chưa nhận dạng được</td></tr></tbody></table>',91)])])}const s=n(o,[["render",g]]);export{m as __pageData,s as default};
